import base64,zlib,json,hashlib,sys,glob,os
from reportlab.pdfgen.canvas import Canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.colors import Color
B64=""
raw=zlib.decompress(base64.b64decode(B64))
assert hashlib.sha256(raw).hexdigest()=="dbfd75497c992115e81c4e39e178a732f4dccf63509fe5164e9da054b9e4109c", "El contenido del regalo no se ha transferido correctamente"
pages=json.loads(raw)
fonts={'Lato-Bold':'Lato-Bold.ttf','Lato-Light':'Lato-Light.ttf','Lato-Regular':'Lato-Regular.ttf','Lato-Medium':'Lato-Medium.ttf','LiberationSerif':'LiberationSerif-Regular.ttf'}
for font,filename in fonts.items():
    matches=glob.glob('/usr/share/fonts/**/'+filename,recursive=True)
    if not matches: raise RuntimeError('Falta fuente '+filename)
    pdfmetrics.registerFont(TTFont(font,matches[0]))
out=sys.argv[1] if len(sys.argv)>1 else 'regalo.pdf'
os.makedirs(os.path.dirname(os.path.abspath(out)),exist_ok=True)
c=Canvas(out,pagesize=(595,842),pageCompression=1,title='Mi primer encuentro contigo · Vida Modo Ohm',author='Vida Modo Ohm')
for text,drawings in pages:
    for d in drawings:
        p=c.beginPath()
        for cmd in d['cmds']:
            if cmd[0]=='re':
                x0,y0,x1,y1=cmd[1];p.rect(x0,842-y1,x1-x0,y1-y0)
            elif cmd[0]=='l':
                p.moveTo(cmd[1][0],842-cmd[1][1]);p.lineTo(cmd[2][0],842-cmd[2][1])
            elif cmd[0]=='c':
                _,start,cp1,cp2,end=cmd;p.moveTo(start[0],842-start[1]);p.curveTo(cp1[0],842-cp1[1],cp2[0],842-cp2[1],end[0],842-end[1])
        if d['fill']:c.setFillColor(Color(*d['fill']))
        if d['color']:c.setStrokeColor(Color(*d['color']))
        if d['width']:c.setLineWidth(d['width'])
        c.drawPath(p,stroke=int('s' in d['type']),fill=int('f' in d['type']))
    for x,y,sz,font,color,s in text:
        c.setFont(font,sz)
        c.setFillColor(Color(((color>>16)&255)/255,((color>>8)&255)/255,(color&255)/255))
        c.drawString(x,842-y,s)
    c.showPage()
c.save()
assert os.path.getsize(out)>40000
print('Generado regalo PDF de seis páginas',out)
